<?php

# @autogenerated
declare(strict_types=1);

use Civi\Lughauth\Features\Notification\Message\Domain\ValueObject\Accessor\MessageLockAtAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the MessageLockAtAccessor trait.
 *
 * Covers null default, string/VO assignment via withLockAt,
 * getLockAt/lockAt accessors, and isLockAtChanged with/without original.
 */
class MessageLockAtAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withLockAt creates a new instance with the LockAt set
     * from a string value, and getLockAt returns the primitive string.
     */
    public function testWithLockAtFromString(): void
    {
        // Arrange
        $holder = new ImplWithMessageLockAtAccessorUnitTest();

        // Act
        $result = $holder->withLockAt((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')));

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')), $result->getLockAt());
    }
    /**
     * Asserts that withlockAt has access to the value object
     * from a string value, and getLockAt returns the primitive string.
     */
    public function testWithLockAtFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithMessageLockAtAccessorUnitTest();

        // Act
        $result = $holder->withLockAt((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')));

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')), $result->lockAt()->value());
    }
    public function testChangedLockAt(): void
    {
        // Arrange
        $holder = new ImplWithMessageLockAtAccessorUnitTest();
        $original = $holder->withLockAt( (new \DateTimeImmutable('1980-08-20T14:32:45.123Z')));
        $same = $holder->withLockAt( (new \DateTimeImmutable('1980-08-20T14:32:45.123Z')));
        $modified = $holder->withLockAt((new \DateTimeImmutable('1981-09-06T14:32:45.123Z')));

        // Act
        $unchanged = $holder->isLockAtChanged();
        $withSame = $original->isLockAtChanged( $same );
        $withDiferent = $original->isLockAtChanged( $modified );

        // Assert
        $this->assertFalse($unchanged);
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithMessageLockAtAccessorUnitTest
{
  use MessageLockAtAccessor;
}
